<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?=htmlspecialchars(csrfToken())?>"><title>Subjects · MYGRADES</title><style><?=mygradebook_asset('styles.css')?></style></head><body><main style="max-width:1180px;margin:30px auto;padding:0 18px"><div class="panel"><div class="panel-heading"><div><h2>Subject Management</h2><p>Add subjects with Semester and School Year.</p></div><a class="btn btn-light" href="teacher.php">Back to Dashboard</a></div><div class="subject-form"><div class="form-field"><label>Subject Code</label><input id="sc"></div><div class="form-field subject-description"><label>Description</label><input id="sd"></div><div class="form-field"><label>Level</label><input id="sl"></div><div class="form-field"><label>Section</label><input id="ss"></div><div class="form-field"><label>Semester</label><select id="sem"><option>1st Semester</option><option>2nd Semester</option><option>Summer</option></select></div><div class="form-field"><label>School Year</label><input id="sy" value="2026-2027"></div><div class="subject-form-action"><button class="btn btn-primary" id="save">+ Add Subject</button></div></div></div><section class="panel" style="padding:0;margin-top:18px"><div class="table-wrap"><table class="data-table"><thead><tr><th>Code</th><th>Description</th><th>Level</th><th>Section</th><th>Semester</th><th>School Year</th><th>Students</th></tr></thead><tbody id="rows"></tbody></table></div></section><div class="toast" id="toast"></div></main><script>
const csrf=document.querySelector('meta[name="csrf-token"]').content;const $=id=>document.getElementById(id);function toast(m){$('toast').textContent=m;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2200)}async function load(){const r=await fetch('api/subjects.php',{credentials:'same-origin'});const d=await r.json();$('rows').innerHTML=(d.subjects||[]).map(s=>`<tr><td>${s.subject}</td><td>${s.description}</td><td>${s.level}</td><td>${s.section}</td><td>${s.semester}</td><td>${s.school_year}</td><td>${s.student_count}</td></tr>`).join('')} $('save').onclick=async()=>{const body={subject:$('sc').value.trim(),description:$('sd').value.trim(),level:$('sl').value.trim(),section:$('ss').value.trim(),semester:$('sem').value,school_year:$('sy').value.trim()};const r=await fetch('api/subjects.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)});const d=await r.json();toast(d.message|| (d.ok?'Subject saved':'Unable to save'));if(d.ok){$('sc').value='';$('sd').value='';load()}};load();
